from .model import Hardware, Software
from .tables import parse_sections, section

BANNER = (
    "_Generated by `make capture` on the laptop. Do not edit by hand: "
    "review `git diff`, then commit to keep or revert and run `make restore`._"
)
NOT_INSTALLED = "not installed"
ABSENT = "absent"


def document(title, blocks):
    lines = [f"# {title}", "", BANNER, ""]
    for block in blocks:
        lines.extend(block)
    return "\n".join(lines).rstrip("\n") + "\n"


def render_hardware(hardware):
    return document(
        "Fedora Laptop Hardware",
        [
            section("System", ("Property", "Value"), hardware.system),
            section(
                "Disks",
                ("Device", "Size", "Model", "Type", "Filesystem", "Label", "Mount"),
                hardware.disks,
            ),
            section("Network", ("Interface", "Kind"), hardware.interfaces),
            section(
                "Persistent mounts",
                ("Mount", "Source", "Type", "Options"),
                hardware.mounts,
            ),
            section("Watched config", ("File", "Key", "Value"), hardware.config),
        ],
    )


def render_software(software):
    return document(
        "Fedora Laptop Software",
        [
            section(
                "Base",
                ("Property", "Value"),
                (
                    ("OS", software.os_name),
                    ("Deployment", software.deployment),
                    ("Kernel", software.kernel),
                    ("Toolbox", software.toolbox or ABSENT),
                ),
            ),
            section("Host layers", ("Package",), [(p,) for p in software.layers]),
            section("Base removals", ("Package",), [(p,) for p in software.removals]),
            section(
                "COPR repositories", ("Repository",), [(r,) for r in software.copr]
            ),
            section(
                "System Flatpaks",
                ("Application", "Version", "Branch", "Origin"),
                software.flatpaks,
            ),
            section(
                "Toolbox packages",
                ("Package", "Version"),
                [(n, v or NOT_INSTALLED) for n, v in software.toolbox_packages],
            ),
            section("Apps", ("App", "Version"), software.apps),
        ],
    )


def column(rows, key):
    return tuple(row[key] for row in rows)


def parse_software(text):
    try:
        return build_software(parse_sections(text))
    except KeyError as error:
        raise ValueError(
            f"software.md is not in the generated format (missing {error}): run make capture"
        ) from error


def build_software(sections):
    base = {row["Property"]: row["Value"] for row in sections["Base"]}
    toolbox = base["Toolbox"]
    return Software(
        os_name=base["OS"],
        deployment=base["Deployment"],
        kernel=base["Kernel"],
        toolbox="" if toolbox == ABSENT else toolbox,
        layers=column(sections["Host layers"], "Package"),
        removals=column(sections["Base removals"], "Package"),
        copr=column(sections["COPR repositories"], "Repository"),
        flatpaks=tuple(
            (r["Application"], r["Version"], r["Branch"], r["Origin"])
            for r in sections["System Flatpaks"]
        ),
        toolbox_packages=tuple(
            (r["Package"], "" if r["Version"] == NOT_INSTALLED else r["Version"])
            for r in sections["Toolbox packages"]
        ),
        apps=tuple((r["App"], r["Version"]) for r in sections["Apps"]),
    )


__all__ = [
    "Hardware",
    "Software",
    "parse_software",
    "render_hardware",
    "render_software",
]
